from pathlib import Path
import json,sys
p=Path(sys.argv[1] if len(sys.argv)>1 else '/tmp/pc-lab.html')
s=p.read_text()
def rep(a,b,n):
 global s
 c=s.count(a)
 if c!=1: raise SystemExit(f'{n}: expected 1 match, got {c}')
 s=s.replace(a,b,1)
rep('<title>PC LAB v2.3.14 — 컴퓨터 조립 시뮬레이터</title><meta name="pc-lab-version" content="2.3.14"><meta name="pc-lab-build" content="2.3.14-96bd6394e936">','<title>PC LAB v2.3.15 — 컴퓨터 조립 시뮬레이터</title><meta name="pc-lab-version" content="2.3.15"><meta name="pc-lab-build" content="2.3.15-1ed8f3203523">','release identity')
rep("systemDisk:'m2'};","systemDisk:'m2',tutorialStep:0};",'tutorial ui state')
