rep("case 'resume':ui.headerMenu=false;closeModal();navigate('work');break;","case 'resume':ui.headerMenu=false;closeModal();navigate('work');break;\n case 'tutorial':tutorialDialog(0);break;\n case 'tutorial-next':tutorialDialog(ui.tutorialStep+1);break;\n case 'tutorial-prev':tutorialDialog(ui.tutorialStep-1);break;\n case 'tutorial-skip':markTutorialSeen();closeModal();toast('튜토리얼을 건너뛰었습니다. 작업실에서 언제든 다시 볼 수 있습니다.');break;\n case 'tutorial-finish':finishTutorial(false);break;\n case 'tutorial-start':finishTutorial(true);break;",'tutorial actions')
